import os
import sqlite3
from flask import Flask, request, jsonify, g
from functools import wraps
import hashlib
import hmac
import time

app = Flask(__name__)
DATABASE = '/var/lib/app/inventory.db'
SECRET = os.environ.get('HMAC_SECRET', 'default-dev-key')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def verify_api_token(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('X-API-Token')
        timestamp = request.headers.get('X-Timestamp')
        if not token or not timestamp:
            return jsonify({'error': 'unauthorized'}), 401
        if abs(time.time() - float(timestamp)) > 300:
            return jsonify({'error': 'expired'}), 401
        expected = hmac.new(SECRET.encode(), timestamp.encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(token, expected):
            return jsonify({'error': 'invalid token'}), 401
        return f(*args, **kwargs)
    return decorated

@app.route('/api/v2/inventory/search', methods=['GET'])
@verify_api_token
def search_inventory():
    """Search inventory items with flexible filtering.
    Supports: category, warehouse, min_qty params.
    Results are paginated via offset/limit.
    """
    category = request.args.get('category', '')
    warehouse = request.args.get('warehouse', '')
    min_qty = request.args.get('min_qty', '0')
    offset = request.args.get('offset', '0')
    limit = request.args.get('limit', '50')

    # Build dynamic query based on provided filters
    conditions = []
    if category:
        conditions.append(f"category = '{category}'")
    if warehouse:
        conditions.append(f"warehouse_code = '{warehouse}'")
    if min_qty:
        conditions.append(f"quantity >= {min_qty}")

    where_clause = ' AND '.join(conditions) if conditions else '1=1'

    query = f"SELECT item_id, name, category, warehouse_code, quantity, unit_price FROM inventory WHERE {where_clause} ORDER BY name LIMIT {limit} OFFSET {offset}"

    try:
        db = get_db()
        cursor = db.execute(query)
        results = [dict(row) for row in cursor.fetchall()]

        # Also get total count for pagination
        count_query = f"SELECT COUNT(*) as total FROM inventory WHERE {where_clause}"
        total = db.execute(count_query).fetchone()['total']

        return jsonify({
            'items': results,
            'total': total,
            'offset': int(offset),
            'limit': int(limit)
        })
    except Exception as e:
        app.logger.error(f"Query failed: {e}")
        return jsonify({'error': 'internal error'}), 500

@app.route('/api/v2/inventory/bulk-update', methods=['POST'])
@verify_api_token
def bulk_update():
    """Bulk update inventory quantities from warehouse scan data."""
    updates = request.json.get('updates', [])
    if not updates or len(updates) > 500:
        return jsonify({'error': 'invalid payload'}), 400

    db = get_db()
    updated = 0
    for item in updates:
        item_id = item.get('item_id')
        new_qty = item.get('quantity')
        if item_id and new_qty is not None:
            db.execute(
                "UPDATE inventory SET quantity = ?, last_scanned = datetime('now') WHERE item_id = ?",
                (new_qty, item_id)
            )
            updated += 1
    db.commit()
    return jsonify({'updated': updated})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
